import { Space, TableProps, Tag, Typography } from "@arco-design/web-react";
import React, { useMemo, useState } from "react";
import { ProTableProps } from "../../ProTable/interface";
import { schemaToTableColumn } from "../utils";
import ProTable from "../../ProTable";

export interface SchemaTableProps extends ProTableProps {
    schema: JSONSchema;
    autoWidth?: boolean;    // 是否自动填充宽度
    fixedLayout?: boolean;
    toolBarRender?: React.ReactNode[];
    /**
     * 需要过滤展示的schema 数据， 同时可以根据 传入顺序进行排序
     */
    filterKeys?: string[];
    headerTitle?: string | React.ReactNode;
    addColumns?: TableProps['columns'];
}
export default ({
    schema,
    autoWidth,
    toolBarRender,
    headerTitle,
    filterKeys,
    fixedLayout,
    addColumns,
    ...props
}: SchemaTableProps) => {

    const columns:TableProps['columns'] = useMemo(() => { 
        let result = schemaToTableColumn(schema);
        if(filterKeys){
            const map =  new Map(result.map((o) => [o.dataIndex, o]));
            result = filterKeys.map((k) => map.get(k)).filter((o) => Boolean(o));
        }
        if(autoWidth){
            const len = result.length - 1;
            result = result.map((o, i) => ({ 
                width: (i == len)? undefined : typeof o.title == "string" ? Math.max(o.title.length * 20, len > 5? 120 : 180): 160,
                ...o
            }));
        }
        if(addColumns){
            result = result.concat(addColumns);
        }
        return result;
    },[schema])

    const header = useMemo(() => {
        if(headerTitle || toolBarRender){
            return (
                <div
                    className="items-center-between"
                    style={{ marginBottom: 15 }}
                >
                    <div style={{ fontSize: '1.2em' }}>
                        {Array.isArray(headerTitle)? headerTitle.map(
                            (o: any) => React.cloneElement(o, { key: Math.random() })
                        ) : headerTitle || null}
                    </div>
                    <Space>
                        {toolBarRender? toolBarRender.map(
                            (o: any) => React.cloneElement(o, { key: Math.random() })
                        ) : null}
                    </Space>
                </div>
            )
        }
        return null;
    },[toolBarRender, headerTitle])



    return (
        <>
            {header}
            <ProTable
                columns={columns}
                fixedLayout={fixedLayout}
                scroll={{
                    x: true,
                    y: true,
                }}
                {...props}
                data={props.data}
            />
        </>
    )
}