import ajax from "@/utils/ajax";
import app from "@/store/app";
import { getModuleItem } from "./module";
import { addCSS } from ".";



/**
 * 获取当前应用所有关联组件
 */
export const getModuleList = (moduleIds) => {
    return ajax.post('/apijson/get', {
        'Module[]': {
          count: 0,
          Module: {
            "moduleId{}": moduleIds,
            platform: app.platform,
            deletedTime: 0,
            "appId": app.appId,
            "@column": "id,moduleId,name,imgUrl,nickname,description,deletedTime,category,display,content,extraInfo,jsxRender,platform,price,manufacturer,props,source" 
          }
        }
    }).then((res) => {
      const list = res.Module.map(getModuleItem)
      // console.log('getModuleItem', list);
      for (const item of list) {
        if(item.source == "custom" && item.extraInfo && item.extraInfo.cssStr){
          addCSS(item.extraInfo.cssStr, item.moduleId);
        }
      }
      
      const map = new Map(list.map((o) => [o.key, o]));
      return moduleIds.map((moduleId) => {
        if(map.has(moduleId)) return map.get(moduleId);
        return getModuleItem({
          moduleId,
          source: 'error',
          name: "Error",
        } as any)
      });
      return list;
    })
}


/**
 * 获取全局组件
 */
export const getAllModuleList = (moduleIds) => {
  return ajax.post('/apijson/get', {
    'Module[]': {
      count: 0,
      Module: {
        "moduleId{}": moduleIds,
        platform: app.platform,
        deletedTime: 0,
        "appId": app.appId,
        "@column": "id,moduleId,name,imgUrl,nickname,description,deletedTime,category,display,content,extraInfo,jsxRender,platform,price,manufacturer,props,source" 
      }
    },
    "PublicModule[]": {
      count: 0,
      PublicModule: {
        "moduleId{}": moduleIds,
        "@column": "id,moduleId,name,imgUrl,nickname,description,category,display,content,extraInfo,jsxRender,platform,price,manufacturer,props,source" 
      }
    }
  }).then((res) => {
    const list = res.Module.map(getModuleItem)
    const plublcs = res.PublicModule.map((item) => getModuleItem({ ...item, isPublic: true }));
    // console.log('getModuleItem', list);
    for (const item of list) {
      if(item.source == "custom" && item.extraInfo && item.extraInfo.cssStr){
        addCSS(item.extraInfo.cssStr, item.moduleId);
      }
    }
    
    const map = new Map(list.map((o) => [o.key, o]));
    const pMap = new Map<string, any>(plublcs.map((o) => [o.key, o]));
    return moduleIds.map((moduleId) => {
      if(map.has(moduleId)) return map.get(moduleId);
      if(pMap.has(moduleId)){
        const pItem = pMap.get(moduleId);
        if(pItem.extraInfo && pItem.extraInfo.cssStr){
          addCSS(pItem.extraInfo.cssStr, pItem.moduleId);
        }
        return pItem;
      }
      return getModuleItem({
        moduleId,
        source: 'error',
        name: "Error",
      } as any)
    });
    return list;
  })
}


/**
 * 获取文件上传配置信息
 */
export const getUploadCalculatePostSignature = () => {
  return ajax.post('/upload/calculatePostSignature', {}, { decrypt: true }).then((res) => {
    return res.data;
  })
}