

/**
 * @name 将大写字符转换为小写并在前面添加下划线
 * 'SomeUppercaseChar'; => 输出: some_uppercase_char
 */
export function convertToSnakeCase(str) {
    const convertedStr = str.replace(/[A-Z]/g, match => '_' + match.toLowerCase());
    
    // 如果第一个字符是下划线，则去除它
    if (convertedStr.charAt(0) === '_') {
      return convertedStr.slice(1);
    }
    
    return convertedStr.replace('.', '');
}