import utils from "utils";
import { datasProps } from "./interface";

const { ajax } = utils;
export default {
  articleTag: {
    find: () => {
      return ajax.post('/apijson/get', {
        "ArchiveTag[]": {
          "count": 0,
          "ArchiveTag": {
            channel: 3
          }
        }
      }).then((res) => res.ArchiveTag)
    }
  },
  markTag: {
    find: () => {
      return ajax.post('/apijson/get', {
        "ArchiveTag[]": {
          "count": 0,
          "ArchiveTag": {
            channel: 8
          }
        }
      }).then((res) => res.ArchiveTag)
    }
  },
  roles: {
    fieldNames: {
      label: 'role_name',
      value: "role_key",
    },
    find: () => {
      return ajax.post('/apijson/get', {
         "Role[]": {
            "Role": {
              "@column": "role_key,role_name"
            },
            "@order": "sort+"
         }
      })
    }
  }
} as {
    [key in string]: datasProps
};
