import changeTheme from '@/utils/changeTheme';
import { setStorageSync } from '@/utils/useStorage';
import { observable, action, computed, makeObservable } from 'mobx';
import { generate, getRgbStr } from '@arco-design/color';
import { ThemeConfig } from '@/types/theme';
import { addCSS, getUuid, removeCss } from '@/utils';
import { AppTheme } from '@/types/app';
import { storageType } from '@/types';


class Store {
    // 当前平台主题（亮色、暗色）
    @observable theme: "dark" | "light"  = "light";
    // 切换当前主题（亮色、暗色）
    @action
    setTheme = (theme) => {
        this.theme = theme;
        setStorageSync('arco-theme', theme);
        if(this.themeColor){
            // 主题色以及修改，需要更新
            this.setThemeColor(this.themeColor); 
        }
        changeTheme()
        localStorage.setItem(storageType.theme, theme);
    }


    key = getUuid();

    // 当前平台主题，主题色
    @observable themeColor: string =  "";
    @action setThemeColor = (color) => {
        if(color){
            // 切换当前主题色
            const list = this.getColorList(color);
            list.forEach((rgb, index) => {
                document.body.style.setProperty(
                    `--arcoblue-${index + 1}`,
                    rgb
                ); 
            });
        }else {
            // 删除之前添加的主题色
            new Array(10).fill(0).forEach((_,index) => {
                document.body.style.removeProperty(`--arcoblue-${index + 1}`,)
            })
        }
        this.themeColor = color;
    }


    // 当前主题总配置
    @observable config:ThemeConfig | null = null;

    constructor() {
        makeObservable(this);
        const theme = localStorage.getItem(storageType.theme);
        if(theme && this.theme != theme){
            this.setTheme(theme);
        }
    }

    @computed get colors(){
        if(this.config) {
            return this.config.colors;
        }
        return {};
    }
    @action setConfig = (config?: ThemeConfig) => {
        if(!config){
            this.setThemeColor(""); // 去掉主色
            this.config = config;
            removeCss(this.key); // 移除配置
            return;
        }
        const { colors } = config;
        this.config = config;
        this.setThemeColor("");
        // 白色
        let list =[];
        for (const key in colors) {
            const name = key.toLowerCase();
            const cols = this.getColorList(colors[key], 'white');
            list = list.concat(cols.map((o,i) => `--${name}-${i}: ${o};`));
        }
        // 黑色
        let darks =[];
        for (const key in colors) {
            const name = key.toLowerCase();
            const cols = this.getColorList(colors[key], 'dark');
            darks = darks.concat(cols.map((o,i) => `--${name}-${i}: ${o};`));
        }

        addCSS(
            `
            :root {
                body {
                    ${list.join('\n')}
                }

                body[arco-theme=dark] {
                    ${darks.join('\n')}
                }
            }
            `,
            this.key
        )
    }

    getColorList = (color, dark?: string) => {
        const newList = generate(color, {
            list: true,
            dark: (dark || this.theme) === 'dark',
        });
        return newList.map((l, index) => {
            const rgbStr = getRgbStr(l);
            return rgbStr;
        });
    }

    /**
    * 主题色配置列表
    */
    themes = {
        red: { name: 'Red / 浪漫红', color: 'rgb(245, 63, 63)' },
        orangeRed: { name: 'Orange Red / 晚秋红', color: 'rgb(247, 114, 52)' },
        orange: { name: 'Orange / 活力橙', color: 'rgb(255, 125, 0)' },
        gold: { name: 'Gold / 黄昏', color: 'rgb(247, 186, 30)' },
        yellow: { name: 'Yellow / 柠檬黄', color: 'rgb(250, 220, 25)' },
        lime: { name: 'Lime / 新生绿', color: 'rgb(159, 219, 29)' },
        green: { name: 'Green / 仙野绿', color: 'rgb(0, 180, 42)' },
        cyan: { name: 'Cyan / 碧涛青', color: 'rgb(20, 201, 201)' },
        blue: { name: 'Blue / 海蔚蓝', color: 'rgb(52, 145, 250)' },
        arcoBlue: { name: 'Arco Blue / 极致蓝', color: 'rgb(22, 93, 255)' },
        purple: { name: 'Purple / 暗夜紫', color: 'rgb(114, 46, 209)' },
        pinkPurple: { name: 'Pink Purple / 青春紫', color: 'rgb(217, 26, 217)' },
        magenta: { name: 'Magenta / 品红', color: 'rgb(245, 49, 157)' },
    };




    // 获取APP 主题色配置
    getAppTheme = (): AppTheme => {

        return {
            isDark: this.theme == "dark",
            themeColor: this.themeColor,
            id: this.config?.name,
            colors: this.config?.colors,
        }
    }

    // 设置APP 主题色
    setAppTheme = (data: AppTheme) => {
        const { isDark, themeColor, id, colors } = data;
        if(isDark) this.setTheme("dark");
        if(id && colors){
            this.setConfig({ name: id, colors })
        }
        this.setThemeColor(themeColor);
    }
}

export default new Store();