import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Select, SelectProps } from '@arco-design/web-react';
import _ from 'lodash'
import datas from './datas';
import { datasProps, ParamsProps } from './interface';
import i18next from 'i18next';

const delayedFunction = (fun: (...arg) => void, time: number = 300) => {
    let timer = null;
    return (...arg) => {
      if(timer){
        clearTimeout(timer);
      }
      timer = setTimeout(() => fun(...arg), time)
    }
}

export interface SelectorProps extends SelectProps {
    // 根据type 置顶数据源
    type?: string;
    // 会将参数作为数据源传给查询接口
    params?: Record<string, any>;
}

const Selector = ({ type, params, ...props}: SelectorProps) => {

    
    const {
        fieldNames, find, onChildNoSelect, isSearch, selectProps
    }: any = useMemo(() => {
        const item: datasProps = datas[type];
        if(!item) return {
            selectProps: {}
        };
        const { fieldNames, find, onChildNoSelect, isSearch, ...itemProps } = item;
        return {
            fieldNames: Object.assign({ 
                label: 'name',
                value: 'id',
                disabled: 'disabled'
            }, fieldNames),
            onChildNoSelect,
            isSearch,
            selectProps: itemProps,
        }
    },[type])


    const [options, setOptions] = useState<any[]>([]);


    const state = useRef({ isOne: true, input: '' });

    const changeOptiosn = async (list) => {
        if(Array.isArray(list)){
            let options = list;
            // 判断 value 值是否存在
            if(props.value && state.current.isOne){
                state.current.isOne = false;
                const values = Array.isArray(props.value)? props.value : [props.value];
                const map = new Map(list.map((o) => [o[fieldNames.value], true]))
                const filters = values.filter((key) => map.has(key));
                if(filters.length){
                    // 存在选中的值，在children 中不存在
                    if(onChildNoSelect){
                        await onChildNoSelect(filters).then((item) => {
                            if(item){
                                const items = Array.isArray(item)? item : [item];
                                options = options.concat(items);
                            }
                        })
                    }
                }
            }
            const result = options.map((o) =>{
                const { label, value, disabled } = fieldNames as datasProps['fieldNames'];
                return {
                    ...o,
                    label: typeof label === 'function'? label(o) : o[label],
                    value: o[value],
                    disabled: o[disabled],
                    extra: o,
                }
            })
            setOptions(result);
        }
    }


    /**
     * 获取筛选内容列表
     */
    const onSearch = useCallback((input: string = '') => {
        state.current.input = input
        if(!find) return ;
        const promise = find({
            input,
            params
        } as ParamsProps)
        promise.then((result) => {
            if(state.current.input == input){
                // 数据不匹配，多次搜索返回最后一次搜索记录
                changeOptiosn(result);
            }
        });
    },[type, params])

    const delayedSearch = useMemo(() => {
        if(!isSearch) return undefined;  // 不需要线上搜索
        return delayedFunction(onSearch, 300)   // 节流控制搜索触发频率
    },[isSearch])
    

    useEffect(() => {
        if(type){
            onSearch()
        }
    },[type, params])

    return (
        <Select
            onSearch={delayedSearch}
            showSearch
            allowClear
            options={options}
            placeholder={i18next.t('please.select')}
            filterOption={(val, option) => {
                const { children, value } = option.props;
                if(children){
                    return children.indexOf(val) !== -1 || (typeof value === "string" && value.indexOf(val) !== -1);
                }
                return true;
            }}
            {...selectProps}
            {...props}
        />
    )
}

export default Selector;