import { action, computed, observable, makeObservable } from "mobx";
import { SchemaPageProps } from "./index";
import utils from "utils";
import _ from "lodash";

type ModeType = "post" | "put";
class Store {

    api: SchemaPageProps['api'];
    data?: any;


    constructor(api: SchemaPageProps['api']){
        makeObservable(this, {
            mode: observable,
            setMode: action,
            visible: observable,
            setVisible: action,
            viewVisible: observable,
            setViewVisible: action,
            pagination: observable,
            resetPagination: action,
            setPagination: action,
            loading: observable,
            list: observable,
            setList: action,
            saveLoading: observable,
            setSaveLoading: action,
            getTableData: action,
            logVisible: observable,
            openLogVisible: action,
            closeLogVisible: action,
            getLogTableData: action,
            getDetail: action,
            selectedRows: observable,
            setSelectedRows: action
        });

        makeObservable(this);
        this.api = api || {};
        this.getTableData();
    }

    // const [visible, setVisible] = useState<boolean>(false);
    // const [viewVisible, setViewVisible] = useState<boolean>(false);

    mode: ModeType = "post";
    setMode = (mode: ModeType) => {
        this.mode = mode;
    };

    visible = false;
    setVisible = (bool) => {
        this.visible = bool;
    };

    viewVisible = false;
    setViewVisible = (bool) => {
        this.viewVisible = bool;
    };
    


    /**
     * 分页信息
     */
    pagination = {
        page: 1,
        size: 10,
        total: 0, 
    };

    resetPagination() {
        this.pagination = {
            page: 1,
            size: 10,
            total: 0,
        }
    }

    setPagination = (params: any) => {
        this.pagination = {
            ...this.pagination,
            ...params
        }
        // console.log('setPagination', this.pagination);
    };


    loading = false;
    list = [];
    setList = (values) => {
        this.list = values;
    };

    saveLoading = false;
    setSaveLoading = (bool) => {
        if(!bool){
            setTimeout(action(() => {
                this.saveLoading = bool;
            }), 300)
        }else {
            this.saveLoading = bool;
        }
    };

    params: any = {};
    resetParams(){
        this.params = {};
    }

    getTableData = () => {
        this.logVisible = false;
        if(this.api.find){
            this.loading = true;
            return this.api.find({
                "current": this.pagination.page,
                "pageSize": this.pagination.size,
                ...this.params
            }).then((res) => {
                this.setList(res.list || []);
                this.setPagination({ total: res.total || 0 })
            }).finally(action(() => {
                this.loading = false;
            }))
        }
    };

    /**
     * 获取日志信息
     */
    logVisible = false;
    logItem = null;
    openLogVisible = (item) => {
        if(this.api.log){
            this.logItem = item;
            this.logVisible = true;
        }
    };
    closeLogVisible = () => this.logVisible = false;
    getLogTableData = (params: any) => {
        console.log('getLogTableData',params)
        if(this.api.log){
            return this.api.log(
                this.logItem,
                params
            )
        }
    };

    getDetail = async (item) => {
        if(this.api.get){
            let data = await this.api.get(item);
            this.data = _.cloneDeep(data);
            if(this.api.getParams){
                const result = this.api.getParams(data);
                if(utils.isPromise(result)) {
                    data = await result;
                }else {
                    data = result;
                }
            }
            return data;
        }{
            return item;
        }
    };

    // 新增数据
    postApi = (form) => {
        if(this.api.post){
            return this.api.post(form);
        }
    }

    // 更新数据
    putApi = (form, data) => {
        // 因为 undefined 通过post传输会自动被删除，所以要进行类型转换
        const keys = Object.keys(form);
        for (const k of keys) {
            if(form[k] === undefined) form[k] = null;
        }
        if(this.api.put){
            return this.api.put(form);
        }
    }

    // 删除数据
    delApi = (item) => {
        if(this.api.del){
            return this.api.del(item);
        }
    }

    // table 选择的数据列表
    selectedRows: any[] = [];
    setSelectedRows = (rows) => {
        this.selectedRows = rows;
    };
}

export default Store;